        pub(crate) fn stable_local_reference_alias_origin(
            program: &dyn crate::CheckingInput,
            current_machine: &Machine,
            machine_symbols: &MachineSymbols<'_>,
            inference: &mut FrameInference,
            local: &typed_trees::statement::TableLocalData,
            parameters: &[StateParameter],
            isolated_local_roots: &[String],
            aliases: &[(String, FramePlaceOrigin)],
            divergent_aliases: &[(String, Vec<FramePlaceOrigin>)],
            symbols: &TopLevelSymbols<'_>,
            stored: &[StoredLocalOrigins],
            include_shared: bool,
        ) -> Option<FramePlaceOrigin> {
            let access = local_declared_reference_access(program, local)?;
            if !access.is_exclusive() && !include_shared {
                let origin = stable_alias_initializer_origin(
                    program,
                    current_machine,
                    machine_symbols,
                    inference,
                    local.initial_value,
                    parameters,
                    isolated_local_roots,
                    aliases,
                    divergent_aliases,
                    symbols,
                    true,
                    stored,
                )?;
                return retained_shared_write_root(&origin, parameters).then_some(origin);
            }
            if include_shared {
                return reference_subjects::backing_origin(
                    program,
                    current_machine,
                    local.initial_value,
                    symbols,
                    inference,
                    aliases,
                    stored,
                );
            }
            stable_alias_initializer_origin(
                program,
                current_machine,
                machine_symbols,
                inference,
                local.initial_value,
                parameters,
                isolated_local_roots,
                aliases,
                divergent_aliases,
                symbols,
                true,
                stored,
            )
        }

